def split_by_separator(grid, sep):
    """Split the grid into blocks separated by every row or column that is one color throughout (any color, incl. sep)."""
    rows=[i for i,row in enumerate(grid) if len(set(row))==1]
    cols=[j for j in range(len(grid[0])) if len({r[j] for r in grid})==1]
    vert=len(rows)>=len(cols)
    if vert:
        idx=[i for i in range(len(grid)) if i not in rows]
        blocks=[[grid[i] for i in g] for g in _groups(idx)]
    else:
        idx=[j for j in range(len(grid[0])) if j not in cols]
        blocks=[[[r[j] for j in g] for r in grid] for g in _groups(idx)]
    return blocks

def _groups(idx):
    out=[];cur=[idx[0]]
    for a,b in zip(idx,idx[1:]):
        if b==a+1: cur.append(b)
        else: out.append(cur);cur=[b]
    out.append(cur);return out

def overlay_mask(blocks, color=2):
    """A grid the size of each block with color where all blocks are non-background(0), else 0."""
    out=[[0]*len(blocks[0][0]) for _ in range(len(blocks[0]))]
    for b in blocks:
        for i,row in enumerate(b):
            for j,v in enumerate(row):
                if v!=0: out[i][j]=color
    return out
